from fastapi import FastAPI

app = FastAPI(title="{{project_name}}")


@app.get("/health")
def health():
    return {"status": "ok"}

from fastmcp import FastMCP

mcp = FastMCP("{{project_name}}")


@mcp.tool
def hello(name: str) -> str:
    """Say hello."""
    return f"Hello, {name}!"


if __name__ == "__main__":
    mcp.run()
